/// <summary>
/// Extension of form PurchAgreement
/// </summary>
[ExtensionOf(formStr(PurchAgreement))]
final class AVAPurchAgreementFrm_Extension
{
}

Method.Source:
/// <summary>
/// Extension of init method
/// </summary>
public void init()
{
    next init();

    agreementHeaderDefault_ds.object(fieldNum(AgreementHeaderDefault, AVAEmail)).registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(PurchAgreement, avaOverrideEmailLookup), this);
}

/// <summary>
/// AVA_007951_BOMItemLookup
/// </summary>
/// <param name = "_formControl">FormStringControl</param>
public void avaOverrideEmailLookup(FormStringControl _formControl)
{
    LogisticsElectronicAddressLookup lookup = LogisticsElectronicAddressLookup::newParameters(_formControl);

    lookup.addParty(ContactPerson::find(AgreementHeaderDefault.ContactPerson).Party);
    lookup.addParty(PurchAgreementHeader.vendTable().Party);

    lookup.parmMethodType(LogisticsElectronicAddressMethodType::Email);
    lookup.performFormLookup();
}

/// <summary>
/// returns a boolean value depending on forms specific values
/// </summary>
/// <returns>boolean</returns>
public boolean avaEnableCallOff()
{
    FormDesign design = this.design();
    return design.controlName(formControlStr(PurchAgreement, buttonReleaseOrderCreate)).isEnabled() && !ALine.AVAStopped;
}
